import {renderSkillPixelIcon} from './skill-pixel-icons.js';
import {SKILL_TREE_DEFINITION} from './skill-tree-definition.js';
import {equipmentIcon} from './equipment-art.js';
import {SOCKETS,SLOTNAME,SOCKET_TYPE,SKILLS} from './engine.js';
import {icon} from './icons.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const conditionName={always:'可用即施放',low:'生命低于60%',charge:'敌人将重击',burn:'目标已灼烧'};
export function renderLoadouts(s,{wardrobeIds,bagItems}){
 const ids=wardrobeIds(s),gear=s.inventory.filter(it=>ids.has(it.id)),plans=Array.from({length:3},(_,i)=>s.loadouts?.[i]||null);
 const treeActive=s.skillTree?.mode==='active',treeNodes=Object.fromEntries(SKILL_TREE_DEFINITION.nodes.map(n=>[n.id,n]));
 const itemById=new Map(s.inventory.map(it=>[it.id,it]));
 return `<div class="panelPage loadoutPage"><div class="loadoutIntro"><div><span class="eyebrow">THE ARMORY</span><h3>备好行装，再赴远征</h3></div><div class="wardrobeCount"><b>${gear.length}</b> 件入柜<span>装备分包共 ${bagItems(s).length} 件 · 各部位50格</span></div></div><div class="loadoutPlans">${plans.map((plan,i)=>`<section class="loadoutCard ${plan?'hasSnapshot':'emptySnapshot'}"><div class="loadoutCardHead"><span class="loadoutNumber">0${i+1}</span><label for="loadoutName${i}" class="loadoutNameLabel">方案名称</label><input id="loadoutName${i}" maxlength="18" value="${esc(plan?.name||'方案'+(i+1))}" aria-label="方案 ${i+1} 名称"></div>${plan?`<div class="loadoutGear">${SOCKETS.map(socket=>{const it=itemById.get(plan.equip[socket]);return `<button class="loadoutGearSlot ${it?'r'+it.rarity:''} ${it?.set?'setFrame':''}" ${it?'data-wardrobeitem="'+esc(it.id)+'"':'disabled'} title="${esc(SLOTNAME[socket]+(it?' · '+it.name:' · 空'))}">${it?equipmentIcon(it):`<span class="loadoutEmptyIcon">${icon(SOCKET_TYPE[socket])}</span>`}<small>${SLOTNAME[socket]}</small></button>`}).join('')}</div><div class="loadoutSkills">${(treeActive?s.skillTree.presets[i].active:plan.skills).map((key,n)=>`<div title="${esc((treeActive?treeNodes[key]?.name:SKILLS[key]?.name)||'空槽')} · ${conditionName[treeActive?s.skillTree.presets[i].conditions[n]:plan.conditions[n]]||'可用即施放'}"><span class="loadoutSkillOrder">${n+1}</span>${treeActive?renderSkillPixelIcon(key):key?icon(key):'<span class="emptyLoadoutSkill">＋</span>'}<small>${esc((treeActive?treeNodes[key]?.name:SKILLS[key]?.name)||'空槽')}</small></div>`).join('')}</div>${treeActive?`<div class="loadoutPriority">被动：${s.skillTree.presets[i].passive.map(key=>`<span class="loadoutPassive">${renderSkillPixelIcon(key)}<span>${esc(treeNodes[key]?.name||'空槽')}</span></span>`).join('')}</div>`:''}<div class="loadoutPriority">从左至右施放 · 条件随方案保存</div>`:`<div class="loadoutEmpty">${icon('bag')}<strong>尚未保存</strong><span>保存当前八栏装备<br>与四项战技、释放条件</span></div>`}<div class="loadoutActions"><button class="primary" data-loadoutapply="${i}" ${plan?'':'disabled'}>切换方案</button><button data-loadoutsave="${i}">${plan?'覆盖当前配置':'保存当前配置'}</button>${plan?`<button class="loadoutDelete" data-loadoutdelete="${i}" title="移除方案；不删除装备">移除</button>`:''}</div></section>`).join('')}</div><div class="wardrobeHeader"><div class="sectionLabel">装备柜</div><span>共享装备只存一件 · 不占普通背包</span></div>${gear.length?`<div class="wardrobeGrid">${gear.map(it=>{let refs=plans.reduce((n,p)=>n+(p&&Object.values(p.equip).includes(it.id)?1:0),0);return `<button class="itemCell r${it.rarity} ${it.set?'setFrame':''}" data-wardrobeitem="${esc(it.id)}" title="${esc(it.name)} · ${refs}套方案引用">${equipmentIcon(it)}<span class="wardrobeRefs">${refs}</span>${it.locked?'<span class="lockedDot">◆</span>':''}${it.divine?'<span class="divineDot" title="神赐">✧</span>':''}</button>`}).join('')}</div>`:'<div class="wardrobeEmpty">保存方案后，引用的装备会自动归入装备柜。</div>'}<p class="loadoutRules">仅在停止远征且没有未结束战斗时切换；天赋不随方案改变。被方案引用的装备不能出售或消耗，改造会同步影响所有引用。覆盖或移除方案不会删除物品。</p></div>`;
}
